    if (selectedMeshes.length === 0) {
      ui.sizeX.value = 0;
      ui.sizeY.value = 0;
      ui.sizeZ.value = 0;
      ui.scaleX.value = 1;
      ui.scaleY.value = 1;
      ui.scaleZ.value = 1;
    }
