  ui.sizeY.value = ui.sizeY.was = (dy / scale2).round(2);
  ui.sizeZ.value = ui.sizeZ.was = (dz / scale2).round(2);
  ui.scaleX.value = ui.scaleX.was = track.scale.x.round(2);
  ui.scaleY.value = ui.scaleY.was = track.scale.y.round(2);
